for(int i = 0; i <= 6; i += 2){
for(int j = 0; j <= 6; j += 2){
filldraw((i, j)--(i+1,j)--(i+1,j+1)--(i,j+1)--cycle, pink);
}
}

for(int i = 0; i <= 7; ++i){
if(i % 2 == 1) draw((i, 0) -- (i, 7), black+linewidth(1.4));
else {draw((i, 0) -- (i, 6), black+linewidth(1.4)); draw((i, 6) -- (i, 7), gray);}
if(i % 2 == 0 && i <= 6) draw((0, i) -- (7, i), black+linewidth(1.4));
else draw((0, i) -- (7, i), gray);
}
draw((1,7)--(7,7), black+linewidth(1.4));
[/asy]
