draw(Arc((-6,0),4,90,270),blue + linewidth(1));
draw(Arc((-6,0),4,-90,90),red + linewidth(1));
draw(Arc((6,0),4,90,270),red + linewidth(1));
draw(Arc((6,0),4,-90,90),blue + linewidth(1));
