		label(pics[1], (string)(n-j), P, N);
		label(pics[2], (string)(n+j-i), P, N);
		label(pic_constr, " $(" + ((string)(i+1)) + "," + ((string)(n-j))
			+ "," + ((string)(n+j-i)) + ")$ ", scale(1.3,1)*P, N);
	}
}

for(int i=0; i<3; ++i){
    add(pics[i].fit(3cm,3cm), (7*i,0));
}
add(pic_constr.fit(6.5cm,5cm), (4.2,-8.5));
