r &= \frac{a'p(k'+q) - k'q(a'+p)}{a'p - k'q} 
&= \frac{\frac{d(de+df-2ef)}{2d-e-f}\left[\frac{ef(d^2+de+df-ef)}{d(de+df+ef-d^2)}-\frac{ef}d\right] + \frac{e^2f^2(d^2+de+df-ef)}{d^2(de+df+ef-d^2)}\left[d+\frac{de+df-2ef}{2d-e-f}\right]}{\frac{d(de+df-2ef)}{2d-e-f} + \frac{e^2f^2(d^2+de+df-ef)}{d^2(de+df+ef-d^2)}} 
&= \frac{2d^2ef(de+df-2ef)(d^2-ef) + 2e^2f^2(d^2+de+df-ef)(d^2-ef)}{d^3(de+df-2ef)(de+df+ef-d^2) + e^2f^2(2d-e-f)(d^2+de+df-ef)} 
&= \frac{2ef(d^2-ef)(d^3e+d^3f-d^2ef+de^2f+def^2-e^2f^2)}{-d^6e-d^6f+d^5e^2+4d^5ef+d^5f^2-d^4e^2f-d^4ef^2+d^2e^3f^2+d^2e^2f^3-de^4f^2-4de^3f^3-de^2f^4+e^4f^3+e^3f^4} 
